eval("\nmodule.exports = {\n    en: {\n        KnowsYourRights: {\n            title: \"KNOWS YOUR RIGHTS\",\n            header: \"Be Aware\",\n            content: ` \n                Thousands of people every day struggle with the flight problems, yet\n                95% of them don’t know their rights. Here is all the information you\n                need to get to know EC 261 regulation, and be aware of your rights as\n                an airline passenger.`,\n            lable1: \"Flight Delay\",\n            info1: \"Thousands of people every day struggle with the flight problems, yet 95% of them don’t know their rights. Here is all the information you need to get to know\\xa0EC 261\\xa0regulation, and be aware of your rights as an airline passenger.\",\n            lable2: \"Flight Cancellation\",\n            info2: \"Just as delays, flight cancellations happen too. If you were not notified 14 days prior you are eligible for compensation.\",\n            lable3: \"Missed Connection\",\n            info3: \"You can’t always get to desired destination with one flight, sometimes you have to use connecting flights. Which depends on the schedules of each other and can be missed even with the slightest delays.\",\n            lable4: \"Damaged / Lost Luggage\",\n            info4: \"A lot of travelers leave their luggage for airlines to handle, there are cases when the luggage is lost, delayed or damaged.\",\n            lable5: \"Denied Boarding\",\n            info5: \"Airlines tend to overbook their flights, and sometimes it so happens that when you show up to your flight there is no more room for you, so you are denied boarding, with or without the reason explained to you. Either way you are eligible for a compensation.\"\n        }\n    },\n    ka: {\n        KnowsYourRights: {\n            title: \"იცოდეთ თქვენი უფლებები\",\n            header: \"\",\n            content: ` ყოველდღიურად ათასობით მგზავრს ექმნება ფრენასთან დაკავშირებული პრობლემები, ამის მიუხედავად 95%-მა არ იცის თავისი, როგორც მგზავრის, უფლებები. აქ შეგიძლიათ გაეცნოთ \"EC 261 რეგულაციას\", თქვენს უფლებებს და გაიგოთ რა შემთხვევაში გეკუთვნით ფრენის კომპენსაცია.`,\n            lable1: \"ფრენის დაგვინება\",\n            info1: \"ავიახაზები ყოველთვის პუნქტუალურები არ არიან და ფრენის დაგვიანებები ხდება. ეს ხშირად უმნიშვნელოა, მაგრამ შესაძლოა ზოგჯერ ჩვენს გეგმებს საფრთე შეუქმნან. ასეთ შემთხვევებში თქვენ შესაძლოა გეკუთვნოდეთ ფრენის კომპენსაცია.\",\n            lable2: \"ფრენის გადადება\",\n            info2: \"ისევე როგორც დაგვიანებები, არც ფრენის გადადებაა იშვიათი. ასეთ შემთხვევაში თუ თქვენ არ მიგიღიათ წინასწარი გაფრთხილება მინიმუმ 14 დღით ადრე, თქვენ გეკუთვნით ფრენის კომპენსაცია.\",\n            lable3: \"დამაკავშირებელი ფრენა\",\n            info3: \"ყოველთვის არ არის შესაძლებელი დანიშნულების ადგილამდე ერთი რეისით ჩასვლა, ზოგჯერ გვჭირდება დამაკავშირებელი რეისები. ეს კი დამოკიდებულია ამ რეისების განრიგზე და პუნქტუალობაზე და შესაძლებელია მცირე დაგვიანებამაც რეისის გამოტოვება გამოიწვიოს. ამ შემთხვევაში შესაძლოა გეკუთვნოდეთ ფრენის კომპენსაცია.\",\n            lable4: \"დაზიანებული/დაკარგული ბარგი\",\n            info4: \"უამრავ მგზავრს უწევს თავიანთი ბარგის ავიახაზებისთვის მინდობა, ზოგჯერ კი მათი დაზიანება და დაკარგვა ხდება. ასეთ შემთხვევაში თქვენ გეკუთვნით ბარგის კომპენსაცია.\",\n            lable5: \"რეისზე არ დაშვება\",\n            info5: \"ავიახაზები ხშირად იმაზე მეტ ბილეთს ყიდიან, ვიდრე რეისზე ადგილია. ამიტომ ხშირად ხდება, რომ თვითმფრინავში ადგილი აღარ არის. თქვენ კი მიზეზის გარეშე ან არასაკმარისი მიზეზით უარს გეუბნებიან ჩასხდომაზე. ასეთ შემთხვევაში თქვენ გეკუთვნით კომპენსაცია\"\n        }\n    }\n};\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./src/components/Knows Your Rights/components/KnowsYourRights.module.js\n");

