eval("\nmodule.exports = {\n    en: {\n        opensection: {\n            sectionTitle: \"DO YOU QUALIFY FOR A COMPENSATION?\",\n            delay: {\n                title: \"Flight Delay Compensation\",\n                desc: \"If your flight is delayed by 3+ hours, according to EU regulations, you are entitled to compensation in the amount of 250-600 euros.\"\n            },\n            compensation: {\n                title: \"Flight Cancellation Compensation\",\n                desc: \"Your flight was delayed and you didn't receive at least 14 days' notice? You're entitled to compensation.\"\n            },\n            missedconnectioncompensation: {\n                title: \"Missed Connection Compensation\",\n                desc: \"Missed your connecting flight due to a flight delay? You may be entitled to flight compensation.\"\n            },\n            overbookingcompensation: {\n                title: \"Overbooking Compensation\",\n                desc: \"Did you show up on time for your flight but couldn't board due to lack of available seats? You are entitled to flight compensation.\"\n            },\n            compensationfordeniedboarding: {\n                title: \"Compensation for denied boarding\",\n                desc: \"Were you denied boarding and given no reason or an insufficient reason? You are entitled to compensation.\"\n            },\n            delayedbaggagecompensation: {\n                title: \"Delayed baggage compensation\",\n                desc: \"Did your checked baggage arrive late or damaged? You are entitled to compensation.\"\n            }\n        }\n    },\n    ka: {\n        opensection: {\n            sectionTitle: \"გეკუთვნით ფრენის კომპენსაცია?\",\n            delay: {\n                title: \"დაგვიანებული ფრენის კომპენსაცია\",\n                desc: \"თუ თქვენმა ფრენამ დაიგვიანა 3+ საათი, ევროკავშირის რეგულაციის მიხედვით თქვენ გეკუთვნით კომპენსაცია 250-600 ევროს ოდენობით.\"\n            },\n            compensation: {\n                title: \"გადადებული ფრენის კომპენსაცია\",\n                desc: \"თქვენი ფრენა გადაიდო და არ მიგიღიათ გაფრთხილება მინიმუმ 14 დღით ადრე? თქვენ გეკუთვნით კომპენსაცია.\"\n            },\n            missedconnectioncompensation: {\n                title: \"დამაკავშირებელი ფრენის კომპენსაცია\",\n                desc: \"გამოტოვეთ დამაკავშირებელი რეისი ფრენის დაგვიანების გამო? თქვენ შესაძლოა გეკუთვნოდეთ ფრენის კომპენსაცია.\"\n            },\n            overbookingcompensation: {\n                title: \"გადაჯავშნილი რეისის კომპენსაცია\",\n                desc: \"დროულად გამოცხადდით რეისზე მაგრამ ვერ მოხვდით თავისუფალი ადგილის არ ქონის გამო? თქვენ ფრენის კომპენსაცია გეკუთვნით.\"\n            },\n            compensationfordeniedboarding: {\n                title: \"რეისზე არ დაშვების კომპენსაცია\",\n                desc: \"უარი გითხრეს ბორდინგზე და არ დაასახელეს მიზეზი ან არასაკმარისი მიზეზი გითხრეს? თქვენ გეკუთვნით კომპენსაცია.\"\n            },\n            delayedbaggagecompensation: {\n                title: \"დაგვიანებული ბარგის კომპენსაცია\",\n                desc: \"თქვენმა ჩაბარებულმა ბარგმა დაიგვიანა ჩამოსვლა ან დაზიანებული ჩამოვიდა? თქვენ გეკუთვნით კომპენსაცია.\"\n            }\n        }\n    }\n};\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./src/components/OptionsSection/opensection.module.js\n");

