"use strict";
eval("\nmodule.exports = {\n    en: {\n        FlightCancellationBeaware: {\n            title: `Be Aware`,\n            item1: {\n                title: `Compensation for business travelers and public officialsCompensation for business travelers and public officials`,\n                desc: `Even if the flight was delayed during the business visit and the ticket was purchased by your employer, you have the right to receive compensation as a victim passenger and not a ticket buyer`\n            },\n            item2: {\n                title: `Provision of food, communication facilities and accommodation`,\n                desc: `The EC 261 law imposes obligation to airline. You as a delayed flight passenger, carrier must provide you with meals and refreshments during the delay as well as access to communications. You also have the right to request international call, send mail or fax and stay in hotel.`\n            },\n            item3: {\n                title: `Alternate flight`,\n                desc: `During the delayed flight, you have the option of a different flight, you have the right to request an alternative flight operator to purchase an alternative ticket. This is also possible even if the new flight class exceeds the ticket class you purchased on the delayed flight.`\n            },\n            item4: {\n                title: `Cash compensation or voucher`,\n                desc: `When your flight is delayed, your airline may offer you compensation in the form of flight vouchers. But be careful - in accordance with the legislation, with the passenger voucher you refuse to accept financial compensation in the future.`\n            }\n        }\n    },\n    ka: {\n        FlightCancellationBeaware: {\n            title: `ყურადღებით`,\n            item1: {\n                title: `კომპენსაცია საქმიანი მოგზაურებისთვის და საჯარო მოხელეებისთვის კომპენსაცია საქმიანი მოგზაურებისთვის და საჯარო მოხელეებისთვის`,\n                desc: `მაშინაც კი, თუ რეისი გადაიდო საქმიანი ვიზიტის დროს და ბილეთი შეიძინა თქვენსმა დამსაქმებელმა, თქვენ გაქვთ უფლება მიიღოთ კომპენსაცია, როგორც დაზარალებული მგზავრი და არა ბილეთის მყიდველი.`\n            },\n            item2: {\n                title: `კვებით, საკომუნიკაციო საშუალებებით და განსახლებით უზრუნველყოფა`,\n                desc: `EC 261 კანონი აკისრებს ვალდებულებას ავიაკომპანიას. თქვენ, როგორც დაგვიანებული ფრენის მგზავრმა, გადამზიდველმა უნდა მოგაწოდოთ კვება და გამაგრილებელი სასმელები დაგვიანების დროს, ასევე კომუნიკაციებზე წვდომა. თქვენ ასევე გაქვთ უფლება მოითხოვოთ საერთაშორისო ზარი, გაგზავნოთ ფოსტა ან ფაქსი და დარჩეთ სასტუმროში.`\n            },\n            item3: {\n                title: `ალტერნატიული ფრენა`,\n                desc: `დაგვიანებული ფრენის დროს თქვენ გაქვთ სხვა ფრენის შესაძლებლობა, თქვენ გაქვთ უფლება მოითხოვოთ ალტერნატიული ფრენის ოპერატორს ალტერნატიული ბილეთის შეძენა. ეს ასევე შესაძლებელია მაშინაც კი, თუ ფრენის ახალი კლასი აღემატება დაგვიანებულ რეისზე შეძენილ ბილეთების კლასს.`\n            },\n            item4: {\n                title: `ფულადი კომპენსაცია ან ვაუჩერი`,\n                desc: `როდესაც თქვენი ფრენა დაგვიანებულია, თქვენმა ავიაკომპანიამ შეიძლება შემოგთავაზოთ კომპენსაცია ფრენის ვაუჩერების სახით. მაგრამ ფრთხილად იყავით - კანონმდებლობის შესაბამისად, სამგზავრო ვაუჩერით უარს იტყვით მომავალში ფინანსური კომპენსაციის მიღებაზე.`\n            }\n        }\n    }\n};\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./src/views/FlightCancellation/BeAware/BeAware.module.js\n");

