eval("\nmodule.exports = {\n    en: {\n        FlightCancellationCompensationIf: {\n            title: `You have the right to claim compensation if:`,\n            _1: `Your flight was cancelled without at least 14 days prior notice;`,\n            _2: `The flight was cancelled no more than three years ago;`,\n            _3: `Flight cancellation is caused by airline;`,\n            _4: `Even if the airline offered you a voucher for food and hotel.`\n        }\n    },\n    ka: {\n        FlightCancellationCompensationIf: {\n            title: `თქვენ გაქვთ უფლება მოითხოვოთ კომპენსაცია, თუ:`,\n            _1: `თქვენი ფრენა გაუქმდა მინიმუმ 14 დღით ადრე გაფრთხილების გარეშე;`,\n            _2: `ფრენა გაუქმდა არაუმეტეს სამი წლის წინ;`,\n            _3: `ფრენის გაუქმება გამოწვეულია ავიაკომპანიის მიერ;`,\n            _4: `თუნდაც ავიაკომპანიამ შემოგთავაზოთ ვაუჩერი კვებისა და სასტუმროსთვის`\n        }\n    }\n};\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./src/views/FlightCancellation/CompensationIf/CompensationIf.module.js\n");

