"use strict";
eval("\nmodule.exports = {\n    en: {\n        FlightDelayBeaware: {\n            title: `Be Aware`,\n            item1: {\n                title: `Compensation for business travelers and public officials`,\n                desc: `Even if the flight was delayed during the business visit and the\n                  ticket was purchased by your employer, you have the right to receive\n                  compensation as a victim passenger and not a ticket buyer.`\n            },\n            item2: {\n                title: `Provision of food, communication facilities and accommodation`,\n                desc: `The EC 261 law imposes obligation to airline. \n                You as a delayed flight passenger, carrier must provide \n                you with meals and refreshments during the delay as well as \n                access to communications. You also have the right to request \n                international call, send mail or fax and stay in hotel.`\n            },\n            item3: {\n                title: `Alternate flight`,\n                desc: `During the delayed flight, you have the option of a different\n                 flight, you have the right to request an alternative flight \n                 operator to purchase an alternative ticket. This is also possible \n                 even if the new flight class exceeds the ticket class you purchased \n                 on the delayed flight.`\n            },\n            item4: {\n                title: `Cash compensation or voucher`,\n                desc: `When your flight is delayed, your airline may offer you \n                compensation in the form of flight vouchers. But be careful – \n                in accordance with the legislation, with the passenger voucher \n                you refuse to accept financial compensation in the future.`\n            }\n        }\n    },\n    ka: {\n        FlightDelayBeaware: {\n            title: `ყურადღებით`,\n            item1: {\n                title: `კომპენსაცია ბიზნეს ვიზიტორთა და ოფიციალურ პირთათვის`,\n                desc: `იმ შემთხვევაშიც კი, თუ რეისის დაგვიანებას საქმიანი ვიზიტის განმავლობაში ქონდა ადგილი, ბილეთი კი თქვენი დამსაქმებლის მიერ იყო შეძენილი, კომპენსაციის მიღების უფლებით სარგებლობთ თქვენ, როგორც დაზარალებული მგზავრი და არა ბილეთის მყიდველი.`\n            },\n            item2: {\n                title: `საკვების, საკომუნიკაციო საშუალებისა და განთავსების უზრუნველყოფა`,\n                desc: `EC 261 კანონი ავიაკომპანიას აკისრებს ვალდებულებას, თქვენ, როგორც დაგვიანებული რეისის მგზავრი, საჭროებიდან და პირობებიდან გამომდინარე უზრუნველგყოთ საკვებით და სასმელით. ასევე, გაქვთ უფლება მოითხოვოთ საერთაშორისო ზარის განხორციელება, ელ. ფოსტის ან ფაქსის გაგზავნა და სასტუმროში განთავსებაც კი.`\n            },\n            item3: {\n                title: `ალტერნატიული რეისი`,\n                desc: `თუ დაგვიანების პერიოდში, თქვენთვის ხელსაყრელ მიმართულებაზე ხელმისაწვდომია სხვა ავიაკომპანიის რეისი, უფლება გაქვთ დაგვიანებული რეისის ოპერატორს მოთხოვოთ ალტერნატიული ბილეთის შეძენა. ეს უფლება გაქვთ მაშინაც კი, თუ ახალი რეისის კლასი, დაგვიანებულ რეისზე თქვენს მიერ შეძენილი ბილეთის კლასს აღემატება.`\n            },\n            item4: {\n                title: `ნაღდი ფული თუ სამზგავრო ვაუჩერი`,\n                desc: `დაგვიანებული რეისის ოპერატორს შეუძლია შემოგთავაზოთ სამგზავრო ვაუჩერი. თუმცა იყავით ყურადღებით – კანონმდებლობის თანახმად, სამგზავრო ვაუჩერის მიღებით თქვენ უარს ამბობთ სამომავლოდ დაგვიანებული ფრენის ანაზღაურებაზე.`\n            }\n        }\n    }\n};\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./src/views/FlightDelay/BeAware/BeAware.module.js\n");

